<script lang="ts">
import { defineComponent } from 'vue';
import type { ExploreEntry } from '../../api/explore';
import type { SearchResult } from '../../api/models';
import AppButton from '../../ui/components/AppButton.vue';
import type { SourceInteractionEffect } from '../../api/sources';
import SourceBrowserSession from '../sources/SourceBrowserSession.vue';
import FeatureScaffold from '../../ui/components/FeatureScaffold.vue';
import SearchResultCard from '../search/components/SearchResultCard.vue';
import { createCandidateSelectionKey, saveCandidateSelection } from '../search/candidate-selection';
import ExploreControls from './ExploreControls.vue';
import { useExploreStore } from './explore-store';

export default defineComponent({name:'ExploreView',components:{AppButton,FeatureScaffold,SearchResultCard,ExploreControls,SourceBrowserSession},data(){return{explore:useExploreStore(),browserEffect:null as SourceInteractionEffect|null,notice:''}},async mounted(){this.explore.initialize();await this.explore.loadSources()},beforeUnmount(){this.explore.stop()},methods:{key(result:SearchResult){return `${result.sourceId}\u0000${result.bookUrl}`},openShelf(result:SearchResult){if(result.shelfBookId)void this.$router.push(`/books/${encodeURIComponent(result.shelfBookId)}`)},open(result:SearchResult){const key=createCandidateSelectionKey();saveCandidateSelection(key,result);this.explore.save();void this.$router.push({name:'candidate-book-detail',query:{candidate:key,from:'explore'}})},updateControl(entry:ExploreEntry,value:string|null){void this.explore.updateControl(entry,value)},async runAction(entry:ExploreEntry){this.notice='';const effects=await this.explore.runAction(entry);for(const effect of effects){if(effect.type==='browser_required'&&effect.browserRequestId)this.browserEffect=effect;else if(effect.type==='notice')this.notice=effect.message||'';else if(effect.type==='refresh_explore')this.explore.refreshSource(this.explore.sourceId)}},browserClosed(saved:boolean){this.browserEffect=null;if(saved){this.notice=this.$t('sources.interaction.effects.loginSaved') as string;this.explore.refreshSource(this.explore.sourceId)}}}});
</script>
<template><FeatureScaffold :title="$t('explore.title')" :description="$t('explore.description')"><div class="layout" :aria-busy="Boolean(explore.busy)"><section class="source-panel"><div><p class="eyebrow">{{ $t('explore.source.eyebrow') }}</p><h2>{{ $t('explore.source.title') }}</h2><p>{{ $t('explore.source.description') }}</p></div><label><span>{{ $t('explore.source.label') }}</span><select :value="explore.sourceId" :disabled="Boolean(explore.busy)" @change="explore.openSource(($event.target as HTMLSelectElement).value)"><option value="">{{ $t('explore.source.choose') }}</option><option v-for="source in explore.sources" :key="source.id" :value="source.id">{{ source.name }}{{ source.group?` · ${source.group}`:'' }}</option></select></label></section><p v-if="explore.busy==='sources'" class="status">{{ $t('explore.status.sources') }}</p><section v-else-if="!explore.sources.length&&!explore.error" class="empty"><h2>{{ $t('explore.empty.sourcesTitle') }}</h2><p>{{ $t('explore.empty.sourcesDescription') }}</p><RouterLink to="/sources">{{ $t('explore.empty.openSources') }}</RouterLink></section><template v-if="explore.catalog"><section class="catalog-heading"><div><p class="eyebrow">{{ $t('explore.catalog.eyebrow') }}</p><h2>{{ explore.catalog.source.name }}</h2><div v-if="explore.catalog.source.group || explore.catalog.source.capabilities?.length" class="source-badges"><em v-if="explore.catalog.source.group" class="source-group">{{ explore.catalog.source.group }}</em><em v-for="capability in explore.catalog.source.capabilities" :key="capability" class="source-capability">{{ $t(`sources.capabilities.${capability}`) }}</em></div><p>{{ $t('explore.catalog.session') }}</p></div></section><ExploreControls :entries="explore.controls" :disabled="Boolean(explore.busy)" @update="updateControl" /><nav v-if="explore.categories.length" class="categories" :aria-label="$t('explore.categories.label')"><template v-for="entry in explore.categories" :key="entry.id"><button v-if="entry.selectable" type="button" :class="{active:explore.categoryId===entry.id}" :aria-pressed="explore.categoryId===entry.id" :disabled="Boolean(explore.busy)" @click="explore.selectCategory(entry)">{{ entry.title }}</button><button v-else-if="entry.actionable" type="button" :disabled="Boolean(explore.busy)" @click="runAction(entry)">{{ entry.title }}</button><strong v-else-if="entry.title">{{ entry.title }}</strong></template></nav><section v-else-if="!explore.controls.length" class="empty"><h2>{{ $t('explore.empty.catalogTitle') }}</h2><p>{{ $t('explore.empty.catalogDescription') }}</p></section></template><p class="status" aria-live="polite"><template v-if="explore.busy==='catalog'">{{ $t('explore.status.catalog') }}</template><template v-else-if="explore.busy==='control'">{{ $t('explore.status.control') }}</template><template v-else-if="explore.busy==='page'&&!explore.results.length">{{ $t('explore.status.books') }}</template><template v-else-if="explore.categoryId&&!explore.results.length&&explore.exhausted">{{ $t('explore.status.empty') }}</template><template v-else-if="explore.results.length&&explore.exhausted">{{ $t('explore.status.complete') }}</template></p><section v-if="explore.error" class="error" role="alert"><span>{{ explore.error }}</span><AppButton v-if="explore.retryable" variant="secondary" @click="explore.retry()">{{ $t('app.common.retry') }}</AppButton></section><ul v-if="explore.diagnostics.length" class="diagnostics"><li v-for="diagnostic in explore.diagnostics" :key="`${diagnostic.code}:${diagnostic.message}`">{{ diagnostic.message }}</li></ul><section v-if="explore.results.length" class="results" :aria-label="$t('explore.results.label')"><header><strong>{{ $t('explore.results.count',{count:explore.results.length}) }}</strong><span>{{ explore.selectedSource?.name }}</span></header><div class="result-list"><div v-for="result in explore.results" :key="key(result)"><SearchResultCard :result="result" @open="open(result)" @open-shelf="openShelf(result)" /></div></div></section><AppButton v-if="explore.categoryId&&explore.results.length&&!explore.exhausted" class="more" variant="secondary" :disabled="Boolean(explore.busy)" @click="explore.loadPage(explore.nextPage,false)">{{ $t('explore.actions.more',{page:explore.nextPage}) }}</AppButton></div><p v-if="notice" class="status" role="status">{{ notice }}</p><SourceBrowserSession v-if="browserEffect?.browserRequestId&&explore.sourceId" :source-id="explore.sourceId" :browser-request-id="browserEffect.browserRequestId" :title="browserEffect.title" @close="browserClosed" /></FeatureScaffold></template>
<style scoped>.layout{display:grid;gap:1rem}.source-panel,.catalog-heading,.empty,.error{display:flex;justify-content:space-between;align-items:center;gap:1.25rem;padding:1rem;border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-paper-raised)}.source-panel h2,.catalog-heading h2,.empty h2{margin:.15rem 0;font:700 1.25rem var(--font-literary)}.source-panel p,.catalog-heading p,.empty p{margin:.2rem 0;color:var(--color-ink-muted);line-height:1.5}.eyebrow{color:var(--color-warm)!important;font-size:.72rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.source-badges{display:flex;flex-wrap:wrap;gap:.25rem;margin:.35rem 0}.source-badges em{border-radius:999px;padding:.18rem .42rem;font-size:.68rem;font-style:normal}.source-badges .source-group{background:var(--color-paper-muted);color:var(--color-ink-muted)}.source-badges .source-capability{background:var(--color-accent-soft);color:var(--color-accent-strong)}.source-panel label{min-width:min(22rem,45%);display:grid;gap:.3rem}.source-panel label span{color:var(--color-ink-muted);font-size:.78rem;font-weight:700}.source-panel select{min-height:2.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.55rem .7rem;background:white;color:var(--color-ink)}.categories{display:flex;align-items:center;flex-wrap:wrap;gap:.45rem}.categories button{min-height:2.75rem;border:1px solid var(--color-border);border-radius:999px;padding:.55rem .85rem;background:var(--color-paper-raised);color:var(--color-ink)}.categories button.active{border-color:var(--color-accent);background:var(--color-accent);color:white}.categories strong{width:100%;margin-top:.4rem;font:700 .88rem var(--font-literary)}.status{min-height:1.25rem;margin:0;color:var(--color-ink-muted);font-size:.84rem}.error{border-color:color-mix(in srgb,var(--color-danger) 45%,var(--color-border));color:var(--color-danger)}.diagnostics{margin:0;padding:0 0 0 1.25rem;color:var(--color-ink-muted);font-size:.82rem}.results header{display:flex;justify-content:space-between;gap:.75rem;margin-bottom:.7rem;color:var(--color-ink-muted)}.result-list{display:grid;gap:.7rem}.notice{margin:.35rem .75rem 0;font-size:.82rem}.success{color:var(--color-success)}.failure{color:var(--color-danger)}.more{width:100%}@media(max-width:42rem){.source-panel,.catalog-heading,.empty,.error{align-items:stretch;flex-direction:column}.source-panel label{min-width:0;width:100%}} </style>
